        assertEquals("c", enumeration.nextElement());
        assertFalse(enumeration.hasMoreElements());

        try {
            enumeration.nextElement();
            fail("NoSuchElementException expected");
        } catch (final NoSuchElementException e) {
            // expected
        }
    }

